// Browser receives only sanitized readings and connection state, never OAuth tokens.
const dexcom={configured:false,connected:false,reading:null,error:null,loading:false,historical:false,authenticated:null,callbackError:null,expectingConnection:false};
const trendLabels={doubleUp:'↑↑ Rising quickly',singleUp:'↑ Rising',fortyFiveUp:'↗ Rising gently',flat:'→ Steady',fortyFiveDown:'↘ Falling gently',singleDown:'↓ Falling',doubleDown:'↓↓ Falling quickly',none:'No trend',unknown:'Trend unavailable',notComputable:'Trend unavailable',rateOutOfRange:'Trend unavailable'};
const dexMessages={setup_required:'Server setup is incomplete. Add the Dexcom credentials as runtime secrets.',sign_in_required:'Sign in to DiaBuddy before connecting Dexcom.',reconnect_required:'Your Dexcom session expired. Connect again.',provider_unavailable:'Dexcom is temporarily unavailable. Try refreshing shortly.',rate_limited:'Dexcom asked us to wait. Try again in a minute.',refresh_in_progress:'Your session is refreshing. Try again shortly.',connection_unavailable:'The connection is unavailable. Please retry.',invalid_origin:'This Site domain does not match the backend OAuth configuration.',state_error:'The connection request expired or its browser cookie was missing. Start again in the same browser tab.',token_exchange_failed:'Dexcom returned to DiaBuddy, but the server could not exchange the authorization code. The administrator can check the safe token-exchange diagnostic.',token_storage_failed:'Dexcom returned to DiaBuddy, but the server could not save or read the encrypted connection. The administrator can check the safe storage diagnostic.',callback_redirect_failed:'The OAuth callback could not finish. The administrator can check the safe callback diagnostic.'};
function dexStale(){return !!dexcom.reading&&(dexcom.reading.stale||Date.now()-Date.parse(dexcom.reading.timestamp)>15*60000)}
function petGlucose(){if(dexcom.error)return 'range';if(!dexcom.connected)return classify(reading);const r=dexcom.reading;return r&&Number.isFinite(r.value)&&!dexStale()&&!r.future&&!dexcom.error?classify(r.value):'range'}
function dexPanel(){const r=dexcom.reading;return `<section class="card card-pad dexcom-panel"><div class="card-title">Dexcom G7 <span class="tiny">SANDBOX · SIMULATED</span></div>${r?`<div class="reading"><strong>${escapeHTML(r.displayValue)}</strong><span>mg/dL</span></div><p>${escapeHTML(trendLabels[r.trend]||'Trend unavailable')}</p><p class="dex-timestamp">Recorded: ${escapeHTML(new Date(r.timestamp).toLocaleString())}</p><div class="dex-badge">${dexStale()?'STALE · Over 15 minutes old':r.future?'TIMESTAMP AHEAD OF SERVER':'RECENT SIMULATED READING'}${dexcom.historical?' · HISTORICAL SAMPLE':''}</div>`:`<p>${dexcom.authenticated===false?'Sign in to this DiaBuddy Site with ChatGPT before connecting Dexcom.':dexcom.connected?'No simulated G7 readings available.':dexcom.configured?'Connect and select Sandbox User - G7.':'Sandbox connection needs server configuration.'}</p>`}${[dexcom.callbackError,dexcom.error].filter((v,i,a)=>v&&a.indexOf(v)===i).map(v=>`<p class="dex-error" role="status">${escapeHTML(v)}</p>`).join('')}<div class="demo-controls">${dexcom.authenticated===false?'<a class="primary" href="/signin-with-chatgpt" target="_top">Sign in to DiaBuddy</a>':dexcom.connected?'<button class="secondary" id="dex-refresh">Refresh readings</button><button class="secondary" id="dex-disconnect">Disconnect</button>':`<button class="primary" id="dex-connect" ${dexcom.configured?'':'disabled'}>Connect Dexcom · Sandbox</button>`}</div><p class="dex-note">Simulated data only. Pet expressions stay neutral across glucose states. Readings never affect coins, happiness, health, or progression.</p></section>`}
function renderDexPanel(){document.querySelectorAll('#dexcom-root, #parent-dexcom-root').forEach(root=>{root.innerHTML=dexPanel();bindDexButtons(root)});const fixture=$('#parent-fixture-glucose');if(fixture)fixture.hidden=dexcom.connected||!!dexcom.reading;}
function bindDexButtons(root){const connect=root.querySelector('#dex-connect'),refresh=root.querySelector('#dex-refresh'),disconnect=root.querySelector('#dex-disconnect');if(connect)connect.onclick=()=>{window.location.href='/api/auth/dexcom/login'};if(refresh)refresh.onclick=()=>refreshDexcom();if(disconnect)disconnect.onclick=async()=>{try{const response=await fetch('/api/dexcom/disconnect',{method:'POST',headers:{'X-SugarPet-Action':'disconnect'},credentials:'same-origin',cache:'no-store'});if(!response.ok)throw Error();Object.assign(dexcom,{connected:false,reading:null,error:null});refreshDexViews()}catch{dexcom.error='Could not disconnect. Please try again.';renderDexPanel()}}}
function refreshDexViews(){renderDexPanel();if(page==='home')drawRoom()}

async function checkDexcom(){try{const response=await fetch('/api/dexcom/status',{cache:'no-store',credentials:'same-origin'});const data=await response.json();if(!response.ok){if(response.status===401){dexcom.authenticated=false;dexcom.connected=false;dexcom.configured=false;}throw new Error(data.error||'connection_unavailable')}dexcom.authenticated=true;dexcom.configured=!!data.configured;dexcom.connected=!!data.connected;dexcom.error=null;if(dexcom.expectingConnection&&!dexcom.connected)dexcom.callbackError='Dexcom returned successfully, but the saved browser connection is unavailable. Keep this Site open in the same browser and connect again.';if(dexcom.connected)dexcom.callbackError=null;dexcom.expectingConnection=false;refreshDexViews();if(dexcom.connected)await refreshDexcom()}catch(e){dexcom.error=dexMessages[e.message]||dexMessages.connection_unavailable;refreshDexViews()}}
async function refreshDexcom(){if(dexcom.loading||!dexcom.connected)return;dexcom.loading=true;try{const response=await fetch('/api/dexcom/egvs',{credentials:'same-origin',cache:'no-store'});let data;try{data=await response.json()}catch{throw new Error('connection_unavailable')}if(!response.ok){if(response.status===401)dexcom.connected=false;throw new Error(data.error||'connection_unavailable')}dexcom.reading=data.reading||null;dexcom.historical=!!data.historical;dexcom.error=data.message||null}catch(e){dexcom.error=dexMessages[e.message]||dexMessages.connection_unavailable}finally{dexcom.loading=false;refreshDexViews()}}
function mountDexcomHome(){const stack=content.querySelector('.side-stack');if(!stack)return;const root=document.createElement('div');root.id='dexcom-root';stack.prepend(root);const fixture=$('#fixture-glucose');if(fixture)fixture.hidden=dexcom.connected||!!dexcom.reading;renderDexPanel()}
function mountDexcomConnections(){const root=document.createElement('div');root.id='dexcom-root';content.prepend(root);renderDexPanel();document.querySelectorAll('[data-provider="Dexcom G7"]').forEach(b=>b.hidden=true)}
if(typeof window.addEventListener==='function')window.addEventListener('load',()=>{
 const params=new URLSearchParams(window.location.search),outcome=params.get('dexcom');
 if(outcome){dexcom.expectingConnection=outcome==='connected';const message=outcome==='connected'?'Dexcom sandbox connected. Loading simulated G7 readings…':outcome==='denied'?'Dexcom authorization was declined. You can connect again whenever you choose.':outcome==='failed'?'An older connection attempt failed without a detailed diagnostic. Please connect again to identify the failed step.':dexMessages[outcome]||'The connection could not be completed. Please try again.';dexcom.callbackError=outcome==='connected'?null:message;toast(message);if(document.querySelector('nav [data-page=settings]'))go('settings');history.replaceState(null,'',window.location.pathname);}
 checkDexcom();setInterval(()=>{if(!document.hidden&&dexcom.connected)refreshDexcom()},60000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)checkDexcom()});
});
